# Effort limits are the MJCF ``actuatorfrcrange`` clamps, which is what mjlab's
# validated MuJoCo policies actually operated under. motor_specs' dyno peak torques are
# HIGHER for some clusters (s4 peak 61 Nm vs the 45 Nm clamp on hip/knee, s3 31 vs 37 on
# hip yaw/torso), and in MuJoCo the joint clamp binds first. If you want the optimistic
# envelope instead, swap these for s*_peak_torque -- but retune before deploying.
B1_CFG = ArticulationCfg(
    spawn=sim_utils.MjcfFileCfg(
        asset_path=f"{ASSET_DIR}/robot_description/mjcf/b1.xml",
        fix_base=False,
        self_collision=True,
        import_physics_scene=False,
        activate_contact_sensors=True,
        collision_type="Convex Hull",
        rigid_props=sim_utils.RigidBodyPropertiesCfg(
            disable_gravity=False,
            retain_accelerations=False,
            linear_damping=0.0,
            angular_damping=0.0,
            max_linear_velocity=1000.0,
            max_angular_velocity=1000.0,
            max_depenetration_velocity=1.0,
        ),
        articulation_props=sim_utils.ArticulationRootPropertiesCfg(
            enabled_self_collisions=True,
            solver_position_iteration_count=8,
            solver_velocity_iteration_count=4,
        ),
    ),
    init_state=ArticulationCfg.InitialStateCfg(
        # Derived, not nominal. The MJCF's carried-over 0.9 left the soles floating
        # 1.92 cm above z=0. Forward kinematics over the home pose puts the lowest foot
        # mesh vertex at +0.0192 m, so 0.9 - 0.0192 = 0.8808 rests them exactly on the
        # ground; +2 mm of clearance avoids first-frame interpenetration (the same
        # reason G1 spawns slightly high). Equivalent to mjlab's compute_home_z().
        # Re-derive with scripts/preview_b1.py if the home pose or foot mesh changes.
        pos=(0.0, 0.0, 0.8828),
        joint_pos={
            "Torso_Rz": 0.0,
            "Neck_Rz": 0.0,
            "Neck_Ry": 0.0,
            "R_Hip_Rx": -_HOME_HIP_RX,
            "L_Hip_Rx": _HOME_HIP_RX,
            ".*_Hip_Rz": 0.0,
            ".*_Hip_Ry": -_HOME_HIP_RY,
            ".*_Knee_Ry": _HOME_KNEE,
            ".*_Ankle_Ry": -_HOME_ANKLE,
            "R_Shoulder_Rx": -_HOME_SHOULDER_RX,
            "L_Shoulder_Rx": _HOME_SHOULDER_RX,
            ".*_Shoulder_Ry": 0.0,
            ".*_Elbow_Ry": -_HOME_ELBOW,
            ".*_Forearm_Rz": 0.0,
            ".*_Wrist_Rx": 0.0,
        },
        joint_vel={".*": 0.0},
    ),
    soft_joint_pos_limit_factor=0.9,
    actuators={
        "legs": ImplicitActuatorCfg(
            joint_names_expr=[".*_Hip_Rx", ".*_Hip_Ry", ".*_Knee_Ry"],
            effort_limit_sim=45.0,
            velocity_limit_sim=VEL_S4,
            stiffness=STIFFNESS_S4,
            damping=DAMPING_S4,
            armature=ARMATURE_S4,
        ),
        "hip_yaw": ImplicitActuatorCfg(
            joint_names_expr=[".*_Hip_Rz"],
            effort_limit_sim=37.0,
            velocity_limit_sim=VEL_S3,
            stiffness=STIFFNESS_S3,
            damping=DAMPING_S3,
            armature=ARMATURE_S3,
        ),
        "torso": ImplicitActuatorCfg(
            joint_names_expr=["Torso_Rz"],
            effort_limit_sim=37.0,
            velocity_limit_sim=VEL_S3,
            stiffness=STIFFNESS_S3,
            damping=DAMPING_S3,
            armature=ARMATURE_S3,
        ),
        "feet": ImplicitActuatorCfg(
            joint_names_expr=[".*_Ankle_Ry"],
            effort_limit_sim=31.0,  # motor 31 Nm x linkage r ~= 1.0; see approximation (1)
            velocity_limit_sim=VEL_S3,
            stiffness=STIFFNESS_ANKLE,
            damping=DAMPING_ANKLE,
            armature=ARMATURE_ANKLE,
        ),
        "shoulders": ImplicitActuatorCfg(
            joint_names_expr=[".*_Shoulder_Rx", ".*_Shoulder_Ry"],
            effort_limit_sim=16.0,
            velocity_limit_sim=VEL_S2,
            stiffness=STIFFNESS_SHOULDER,
            damping=DAMPING_SHOULDER,
            armature=ARMATURE_S2,
        ),
        "elbows": ImplicitActuatorCfg(
            joint_names_expr=[".*_Elbow_Ry"],
            effort_limit_sim=36.57,
            velocity_limit_sim=VEL_S2E,
            stiffness=STIFFNESS_ELBOW,
            damping=DAMPING_ELBOW,
            armature=ARMATURE_S2E,
        ),
        "wrists": ImplicitActuatorCfg(
            joint_names_expr=[".*_Forearm_Rz", ".*_Wrist_Rx"],
            effort_limit_sim={".*_Forearm_Rz": 2.5, ".*_Wrist_Rx": 7.5},
            velocity_limit_sim=VEL_S1,
            stiffness=STIFFNESS_S1,
            damping=DAMPING_S1,
            armature=ARMATURE_S1,
        ),
        "neck": ImplicitActuatorCfg(
            joint_names_expr=["Neck_Rz", "Neck_Ry"],
            effort_limit_sim=2.5,
            velocity_limit_sim=VEL_S1,
            stiffness=STIFFNESS_S1,
            damping=DAMPING_S1,
            armature=ARMATURE_S1,
        ),
    },
)

# Same 0.25 * effort / stiffness rule the G1 config uses.
#
# WARNING -- the size-1 cluster comes out nearly frozen. With effort 2.5 Nm against
# kp 72, Neck_* and *_Forearm_Rz get scale 0.0087, i.e. ~0.5 deg of authority at a
# full-scale action; *_Wrist_Rx gets 0.026. For comparison the big joints land at
# 0.16-0.37, right alongside G1's hip (0.35), and even G1's weakest joint (wrist pitch)
# is 0.0745 -- 8.5x more than B1's neck. So the policy effectively cannot use the neck
# or forearm roll as configured.
#
# This is a consequence of pairing the MJCF's physical actuatorfrcrange with mjlab's
# firmware kp. mjlab avoids it by giving that cluster effort_limit=500 -- an intentional
# flat clamp, not a real torque. Two honest fixes, both needing a retune:
#   (a) lower STIFFNESS_S1 (the 0.5 deg is the kp's fault as much as the torque's), or
#   (b) follow mjlab and raise the size-1 effort limit, accepting that sim will then
#       believe in torque the motors do not have.
# We keep the real 2.5/7.5 Nm here so sim2real is not silently optimistic. Revisit
# before expecting expressive head or forearm motion.
B1_ACTION_SCALE = {}
for a in B1_CFG.actuators.values():
    e = a.effort_limit_sim
    s = a.stiffness
    names = a.joint_names_expr
    if not isinstance(e, dict):
        e = dict.fromkeys(names, e)
    if not isinstance(s, dict):
        s = dict.fromkeys(names, s)
    for n in names:
        if n in e and n in s and s[n]:
            B1_ACTION_SCALE[n] = 0.25 * e[n] / s[n]
